steps.script:
var d = tree.root.get_node_or_null("StratagemDialog")
if d and d.visible and int(PhaseManager.get_current_phase_instance().get_pending_stratagem_window_decider()) == 1:
	d.get_node("Content/DeclineButton").emit_signal("pressed")
return true

var d = tree.root.get_node_or_null("StratagemDialog")
if d and d.visible and int(PhaseManager.get_current_phase_instance().get_pending_stratagem_window_decider()) == 2:
	d.get_node("Content/DeclineButton").emit_signal("pressed")
return true

var hc = PhaseManager.get_current_phase_instance().resolution_state.get("staged_hit_context", {})
var n := 0
for e in hc.get("hit_evals", []):
	if e.get("rerolled", false):
		n += 1
return n > 0

var d = tree.root.get_node("Main").get_node("ShootingController").resolution_dock
for c in d.reroll_row.get_children():
	if c.disabled and c.get_node_or_null("RerolledMark") != null and c.tooltip_text.begins_with("Already re-rolled (1→"):
		return true
return false

var d = tree.root.get_node("Main").get_node("ShootingController").resolution_dock
var hc = PhaseManager.get_current_phase_instance().resolution_state.get("staged_hit_context", {})
var evals = hc.get("hit_evals", [])
var kids = d.reroll_row.get_children()
for i in range(evals.size()):
	if evals[i].get("rerolled", false) and int(evals[i].get("reroll_to", 0)) > 1 and not kids[i].tooltip_text.ends_with("→%d) — a dice can never be re-rolled more than once" % int(evals[i].reroll_to)):
		return false
return true

var panel = null
for n in tree.root.get_node("Main").find_children("*", "", true, false):
	if n.get("_tab_dice_button") != null:
		panel = n
		break
if panel == null:
	return "panel not found"
for l in panel.find_children("*", "Label", true, false):
	if l.text.contains("(re-rolled 1→"):
		return true
for r in panel.find_children("*", "RichTextLabel", true, false):
	if r.get_parsed_text().contains("(re-rolled 1→"):
		return true
return false

var found := false
for n in tree.root.get_node("Main").find_children("*", "", true, false):
	if n.get("_context_label") != null and n.visible and str(n._context_label).begins_with("Hit Rolls") and str(n._context_label).contains("re-rolled 1→"):
		found = true
return found
